import sys

def func(x, n):
    return -n*(n*n - 3*n - 3*x*x + 9*x - 4) / (2*(x - 2)*(x - 1)*x)

def main():
    input_line = sys.stdin.readline().strip()
    tokens = input_line.split()
    x = int(tokens[0])
    p = float(tokens[1])
    ans = 0
    for i in range(x + 1):
        if func(x, i) >= p:
            ans = i
            break
    print(ans)

if __name__ == "__main__":
    main()

